#!/usr/bin/env bash
set -Eeuo pipefail

# Sana-Chan single-file Linux installer.
# This installer does not contain .env, Discord tokens, SQLite databases,
# media uploads, backups, virtualenvs, or Python cache files.
#
# Usage:
#   chmod +x Sana-Chan-Linux-Installer.sh
#   ./Sana-Chan-Linux-Installer.sh
#
# Optional environment overrides:
#   SANA_APP_DIR=/home/ubuntu/discord-screenshot-bot
#   SANA_APP_USER=ubuntu
#   SANA_CREATE_APP_USER=1         # create SANA_APP_USER if it is missing
#   SANA_ENV_FILE=/etc/sana-bot/sana.env
#   SANA_DASHBOARD_BIND=127.0.0.1:5000
#   SANA_SKIP_SERVICES=1            # extract and compile only
#   SANA_SKIP_PACKAGES=1            # skip automatic OS package installation
#   SANA_INSTALL_JOURNAL_LIMITS=1   # install journald retention limits

APP_DIR="${SANA_APP_DIR:-${SDAC_APP_DIR:-/home/ubuntu/discord-screenshot-bot}}"
APP_USER="${SANA_APP_USER:-${SDAC_APP_USER:-$(id -un)}}"
CREATE_APP_USER="${SANA_CREATE_APP_USER:-${SDAC_CREATE_APP_USER:-0}}"
ENV_FILE="${SANA_ENV_FILE:-${SDAC_ENV_FILE:-/etc/sana-bot/sana.env}}"
DASHBOARD_BIND="${SANA_DASHBOARD_BIND:-${SDAC_DASHBOARD_BIND:-127.0.0.1:5000}}"
SKIP_SERVICES="${SANA_SKIP_SERVICES:-${SDAC_SKIP_SERVICES:-0}}"
INSTALL_JOURNAL_LIMITS="${SANA_INSTALL_JOURNAL_LIMITS:-${SDAC_INSTALL_JOURNAL_LIMITS:-0}}"
SKIP_PACKAGES="${SANA_SKIP_PACKAGES:-${SDAC_SKIP_PACKAGES:-${SDAC_SKIP_APT:-0}}}"
PAYLOAD_SHA256="0b40485b2381bb0969bead0338e89c3dfcea35f52c3f4f2bf912fc5c83799214"
PAYLOAD_SIZE_BYTES="351554"
SANA_INSTALLER_VERSION="4.4.0"
STAMP="$(date -u +%Y%m%d-%H%M%S)"

say() {
    printf '\n==> %s\n' "$*"
}

fail() {
    echo "ERROR: $*" >&2
    exit 1
}

need_command() {
    command -v "$1" >/dev/null 2>&1 || fail "Missing required command: $1"
}

if [[ "$(uname -s)" != "Linux" ]]; then
    fail "This installer is intended for Linux. Build/run it on Ubuntu for production."
fi

need_command base64
need_command tar
need_command sudo

if ! id "$APP_USER" >/dev/null 2>&1; then
    if [[ "$CREATE_APP_USER" == "1" ]]; then
        say "Creating system user $APP_USER"
        sudo useradd --system --home-dir "$APP_DIR" --shell /usr/sbin/nologin --no-create-home "$APP_USER"
    else
        fail "User $APP_USER does not exist. Create it, use SANA_APP_USER=$(id -un), or set SANA_CREATE_APP_USER=1."
    fi
fi

install_system_prereqs() {
    if [[ "$SKIP_PACKAGES" == "1" ]]; then
        say "Skipping system package installation because SANA_SKIP_PACKAGES=1"
        return
    fi

    if command -v apt-get >/dev/null 2>&1; then
        say "Installing Debian/Ubuntu runtime packages"
        sudo apt-get update
        sudo DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends \
            ca-certificates curl git sqlite3 python3 python3-dev python3-pip python3-venv \
            build-essential pkg-config libffi-dev libssl-dev libjpeg-dev zlib1g-dev libwebp-dev \
            libpq-dev libpq5 libarchive-tools p7zip-full unar unzip xz-utils zstd ffmpeg nginx \
            certbot python3-certbot-nginx lsof jq rsync
        return
    fi

    if command -v dnf >/dev/null 2>&1; then
        say "Installing Fedora/RHEL/Oracle runtime packages with dnf"
        sudo dnf install -y \
            ca-certificates curl git sqlite python3 python3-devel python3-pip gcc gcc-c++ make \
            pkgconf-pkg-config libffi-devel openssl-devel libjpeg-turbo-devel zlib-devel libwebp-devel \
            libpq-devel libarchive p7zip p7zip-plugins unar unzip xz zstd ffmpeg nginx certbot \
            python3-certbot-nginx lsof jq rsync
        return
    fi

    if command -v yum >/dev/null 2>&1; then
        say "Installing RHEL/Oracle runtime packages with yum"
        sudo yum install -y \
            ca-certificates curl git sqlite python3 python3-devel python3-pip gcc gcc-c++ make \
            pkgconfig libffi-devel openssl-devel libjpeg-turbo-devel zlib-devel libwebp-devel \
            libpq-devel libarchive p7zip p7zip-plugins unar unzip xz zstd ffmpeg nginx certbot \
            python3-certbot-nginx lsof jq rsync
        return
    fi

    if command -v apk >/dev/null 2>&1; then
        say "Installing Alpine runtime packages"
        sudo apk add --no-cache \
            ca-certificates curl git sqlite python3 py3-pip py3-virtualenv python3-dev build-base \
            pkgconf libffi-dev openssl-dev jpeg-dev zlib-dev libwebp-dev postgresql-dev libarchive-tools \
            p7zip unrar unzip xz zstd ffmpeg nginx certbot certbot-nginx lsof jq rsync
        return
    fi

    if command -v pacman >/dev/null 2>&1; then
        say "Installing Arch runtime packages"
        sudo pacman -Sy --needed --noconfirm \
            ca-certificates curl git sqlite python python-pip base-devel pkgconf libffi openssl libjpeg-turbo \
            zlib libwebp postgresql-libs libarchive p7zip unrar unzip xz zstd ffmpeg nginx certbot \
            certbot-nginx lsof jq rsync
        return
    fi

    fail "No supported package manager was found. Install Python 3, venv, pip, git, curl, archive tools, nginx, and build libraries manually."
}

install_system_prereqs

if ! command -v python3 >/dev/null 2>&1; then
    fail "python3 is missing and could not be installed automatically."
fi

if ! python3 -m venv --help >/dev/null 2>&1; then
    fail "python3-venv is missing and could not be installed automatically."
fi
say "Preparing $APP_DIR"
sudo mkdir -p "$APP_DIR"
CURRENT_USER="$(id -un)"
CURRENT_GROUP="$(id -gn)"
sudo chown -R "$CURRENT_USER":"$CURRENT_GROUP" "$APP_DIR" 2>/dev/null || sudo chown -R "$CURRENT_USER" "$APP_DIR"
mkdir -p "$APP_DIR/media" "$APP_DIR/backups" "$APP_DIR/deploy-backups"

if [[ -f "$APP_DIR/bot.py" || -f "$APP_DIR/dashboard.py" ]]; then
    DEPLOY_BACKUP_DIR="$APP_DIR/deploy-backups/installer-$STAMP"
    say "Creating deploy snapshot at $DEPLOY_BACKUP_DIR"
    mkdir -p "$DEPLOY_BACKUP_DIR"
    for file in \
        bot.py \
        dashboard.py \
        dashboard_account_templates.py \
        dashboard_admin_roles.py \
        dashboard_shell_assets.py \
        dashboard_sidebar.py \
        config.py \
        database_migrations.py \
        observability.py \
        requirements.txt \
        README.md \
        HOSTING.md \
        DEPLOY.md \
        PRODUCTION_NEXT.md \
        MONITORING.md \
        POSTGRESQL.md \
        DISCORD_PERMISSIONS.md
    do
        if [[ -e "$APP_DIR/$file" ]]; then
            cp -a "$APP_DIR/$file" "$DEPLOY_BACKUP_DIR/"
        fi
    done
    for directory in scripts systemd nginx; do
        if [[ -d "$APP_DIR/$directory" ]]; then
            mkdir -p "$DEPLOY_BACKUP_DIR/$directory"
            cp -a "$APP_DIR/$directory/." "$DEPLOY_BACKUP_DIR/$directory/"
        fi
    done
fi

if [[ -f "$APP_DIR/sdac.db" ]]; then
    DB_BACKUP="$APP_DIR/backups/sdac-pre-installer-$STAMP.db"
    say "Creating SQLite backup at $DB_BACKUP"
    SDAC_DB_FILE="$APP_DIR/sdac.db" SDAC_DB_BACKUP="$DB_BACKUP" python3 - <<'PY'
import os
import sqlite3

source_path = os.environ["SDAC_DB_FILE"]
backup_path = os.environ["SDAC_DB_BACKUP"]
source = sqlite3.connect(source_path)
destination = sqlite3.connect(backup_path)
try:
    with destination:
        source.backup(destination)
finally:
    destination.close()
    source.close()
print(f"Database backup created: {backup_path}")
PY
fi

TMP_DIR="$(mktemp -d)"
cleanup() {
    rm -rf "$TMP_DIR"
}
trap cleanup EXIT
PAYLOAD_FILE="$TMP_DIR/sana-payload.tar.gz"

say "Extracting embedded Sana-Chan payload"
awk '/^__SANA_PAYLOAD_BELOW__$/ {found=1; next} found {print}' "$0" | base64 -d > "$PAYLOAD_FILE"
ACTUAL_SHA256="$(sha256sum "$PAYLOAD_FILE" | awk '{print $1}')"
if [[ "$ACTUAL_SHA256" != "$PAYLOAD_SHA256" ]]; then
    fail "Embedded payload checksum mismatch. Expected $PAYLOAD_SHA256 but got $ACTUAL_SHA256."
fi
ACTUAL_SIZE="$(wc -c < "$PAYLOAD_FILE" | tr -d ' ')"
if [[ "$ACTUAL_SIZE" != "$PAYLOAD_SIZE_BYTES" ]]; then
    fail "Embedded payload size mismatch. Expected $PAYLOAD_SIZE_BYTES but got $ACTUAL_SIZE."
fi

tar -xzf "$PAYLOAD_FILE" -C "$APP_DIR"
chmod +x "$APP_DIR"/scripts/*.sh
mkdir -p "$APP_DIR/media" "$APP_DIR/backups"

if [[ "$SKIP_SERVICES" == "1" ]]; then
    say "Compiling Python files without installing services"
    python3 -m py_compile "$APP_DIR/bot.py" "$APP_DIR/dashboard.py" "$APP_DIR/dashboard_account_templates.py" "$APP_DIR/dashboard_admin_roles.py" "$APP_DIR/dashboard_shell_assets.py" "$APP_DIR/dashboard_sidebar.py" "$APP_DIR/config.py" "$APP_DIR/database_backend.py"
    python3 -m py_compile "$APP_DIR/database_migrations.py" "$APP_DIR/observability.py" "$APP_DIR/scripts/migrate_database.py" "$APP_DIR/scripts/export_sqlite_to_postgres.py" "$APP_DIR/scripts/release_readiness.py"
    echo "Sana-Chan files extracted to $APP_DIR"
    exit 0
fi

say "Running Sana-Chan installer"
export SANA_APP_DIR="$APP_DIR"
export SANA_APP_USER="$APP_USER"
export SANA_ENV_FILE="$ENV_FILE"
export SANA_DASHBOARD_BIND="$DASHBOARD_BIND"
bash "$APP_DIR/scripts/install_ubuntu.sh"

if [[ "$INSTALL_JOURNAL_LIMITS" == "1" ]]; then
    say "Installing journald retention limits"
    bash "$APP_DIR/scripts/install_journal_limits.sh"
fi

say "Sana-Chan single-file install complete"
echo "Installer result: SUCCESS"
echo "Installer version: $SANA_INSTALLER_VERSION"
echo "App directory: $APP_DIR"
echo "Environment file: $ENV_FILE"
echo "Logs:"
echo "  journalctl -u sana-bot -n 80 --no-pager"
echo "  journalctl -u sana-dashboard -n 80 --no-pager"
echo "Health:"
echo "  curl http://127.0.0.1:5000/health"

exit 0

